    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find vertically separated groups of foreground rows.
    groups = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        band = []
        while r < h and any(v != bg for v in grid[r]):
            band.append(r)
            r += 1
        groups.append(band)

    if len(groups) < 2:
        return out
    a, b = groups[0], groups[1]
    if len(a) != len(b):
        return out

    # Column signatures let us detect matching portions even when one band
    # is horizontally displaced.
    def sig(rows, c):
        return tuple(grid[rr][c] for rr in rows)

    best = None
    for shift in range(-w + 1, w):
        run = 0
        for c in range(w):
            d = c - shift  # column in band b corresponding to c in band a
            match = False
            if 0 <= d < w:
                sa, sb = sig(a, c), sig(b, d)
                match = sa == sb and any(x != bg for x in sa)
            if match:
                run += 1
                if best is None or run > best[0]:
                    best = (run, shift, c)
            else:
                run = 0

    # Find rightmost foreground column in a band.
    def rightmost(rows):
        return max((c for rr in rows for c, v in enumerate(grid[rr]) if v != bg),
                   default=-1)

    if best and best[0] >= 5:
        run_len, shift, end_a = best
        start_a = end_a - run_len + 1

        if shift != 0:
            # Mark the unmatched right-hand extension of whichever band
            # continues beyond the aligned shared portion.
            end_b_aligned = rightmost(b) + shift
            end_a_all = rightmost(a)
            if end_a_all > end_b_aligned:
                for rr in a:
                    for c in range(end_a + 1, end_a_all + 1):
                        out[rr][c] = 1
            else:
                end_b_all = rightmost(b)
                start_b = end_a - shift + 1
                for rr in b:
                    for c in range(start_b, end_b_all + 1):
                        if 0 <= c < w:
                            out[rr][c] = 1
            return out

        # For aligned bands, highlight the differing tail after their shared
        # prefix. Keep original foreground only where both bands have it.
        for ra, rb in zip(a, b):
            mismatches = [
                c for c in range(end_a + 1, w)
                if (grid[ra][c] != bg) != (grid[rb][c] != bg)
            ]
            if not mismatches:
                continue
            last = max(
                (c for c in range(w)
                 if grid[ra][c] != bg or grid[rb][c] != bg),
                default=-1
            )
            for c in range(mismatches[0], last + 1):
                if grid[ra][c] == bg or grid[rb][c] == bg:
                    out[ra][c] = 1
        return out

    # If the bands do not share a long matching run, extend each shorter row
    # to the right edge of its corresponding longer row.
    for ra, rb in zip(a, b):
        ea = max((c for c, v in enumerate(grid[ra]) if v != bg), default=-1)
        eb = max((c for c, v in enumerate(grid[rb]) if v != bg), default=-1)
        if ea < eb:
            for c in range(ea + 1, eb + 1):
                out[ra][c] = 1
        elif eb < ea:
            for c in range(eb + 1, ea + 1):
                out[rb][c] = 1

    return out
